def get_bot_pack(bot_number):
    idx = (bot_number - 1) % len(PACKS)
    return PACKS[idx]

def get_bot_premium_emoji(bot_number):
    pack = get_bot_pack(bot_number)
    emojis = pack.get("emojis", [])
    if not emojis:
        return "✅", "0"
    pick = emojis[(bot_number - 1) % len(emojis)]
    return pick[0], pick[1]

