def extract_retry_after(error_str):
    match = re.search(r'retry after (\d+)', error_str.lower())
    return int(match.group(1)) if match else None

class KowkaEngine:
    def __init__(self, bot_number, owner_id):
        self.bot_number = bot_number
        self.owner_id = owner_id
        self.emoji_char, self.emoji_id = get_bot_premium_emoji(bot_number)
        self.pack = get_bot_pack(bot_number)
        self.sudo_users = set(SUDO_IDS)
        self.active_tasks = {}
        self.chat_delays = {}
        self.chat_threads = {}
        self.locks = {}
        self.active_react_chats = {}
        self.pending_replies = {}
        self.active_rr_targets = {}
        self.pending_rr_replies = {}
        self.active_rrspam_tasks = {}

    def get_lock(self, chat_id):
        if chat_id not in self.locks:
            self.locks[chat_id] = asyncio.Lock()
        return self.locks[chat_id]

    async def check_owner(self, update):
        user = update.effective_user
        if not user or user.id != self.owner_id and user.id not in self.sudo_users:
            await update.message.reply_text("-# 𝙂𝙚𝙩 𝙎𝙪𝙙𝙤 𝙛𝙞𝙧𝙨𝙩 𝙩𝙝𝙚𝙣 𝙘𝙤𝙢𝙚 💘")
