    async def nc_loop(self, chat_id, base_name, context, variant):
        msgs = NC_BASE_MESSAGES
        idx = 0
        success = 0
        print(f"[Bot {self.bot_number}] NIKNC LOOP #{variant} started chat {chat_id}")
        try:
            while True:
                delay = self.chat_delays.get(chat_id, 0)
                try:
                    msg = msgs[idx % len(msgs)]
                    title = msg.format(target=base_name)
                    await context.bot.set_chat_title(chat_id=chat_id, title=title)
                    idx += 1
                    success += 1
                    GLOBAL_STATS["name_changes"] += 1
                    if delay > 0:
                        await asyncio.sleep(delay)
                except asyncio.CancelledError:
                    raise
                except RetryAfter as ex:
                    wt = int(ex.retry_after) if isinstance(ex.retry_after,(int,float)) else ex.retry_after.total_seconds()
                    await asyncio.sleep(wt + 1.0)
                except (TimedOut, NetworkError):
                    await asyncio.sleep(2.0)
                except Exception:
                    await asyncio.sleep(2.0)
                    idx += 1
        except asyncio.CancelledError:
            print(f"[Bot {self.bot_number}] NIKNC LOOP #{variant} stopped after {success} changes")

    async def _nc_generic(self, update, context, variant):
        if not await self.check_owner(update):
            return
        chat = update.effective_chat
        if chat.type not in [ChatType.GROUP, ChatType.SUPERGROUP]:
            await update.message.reply_text("This command only works in groups!")
            return
        if not context.args:
            await update.message.reply_text(f"Usage: .niknc{variant} <name>")
            return
        base_name = " ".join(context.args)
        chat_id = chat.id
        if chat_id in self.active_tasks:
            for t in self.active_tasks[chat_id]:
                t.cancel()
            for t in self.active_tasks[chat_id]:
                try:
                    await t
                except asyncio.CancelledError:
                    pass
            del self.active_tasks[chat_id]
        num_threads = self.chat_threads.get(chat_id, 1)
        tasks = [asyncio.create_task(self.nc_loop(chat_id, base_name, context, i+1)) for i in range(num_threads)]
        self.active_tasks[chat_id] = tasks
        e = self.emoji_char
        await update.message.reply_text(f"{e} [Bot {self.bot_number}] ⚡ 𝗡𝗜𝗞𝗡𝗖{variant} 𝗟𝗢𝗢𝗣 𝘀𝘁𝗮𝗿𝘁𝗲𝗱 𝘄𝗶𝘁𝗵 {num_threads} 𝘁𝗵𝗿𝗲𝗮𝗱𝘀! 🔥")

