    async def _stop_all_tasks(self, update):
        chat_id = update.effective_chat.id
        stopped = False
        if chat_id in self.active_tasks:
            for t in self.active_tasks[chat_id]:
                t.cancel()
            for t in self.active_tasks[chat_id]:
                try:
                    await t
                except asyncio.CancelledError:
                    pass
            del self.active_tasks[chat_id]
            stopped = True
        return stopped

